    seen = [[False]*w for _ in range(h)]
    blobs = []
    for y in range(h):
        for x in range(w):
            if not mask[y][x] or seen[y][x]:
                continue
            stack = [(x,y)]
            seen[y][x] = True
            pts = []
            while stack:
                cx,cy = stack.pop()
                pts.append((cx,cy))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
