                    if 0<=nx<w and 0<=ny<h and mask[ny][nx] and not seen[ny][nx]:
                        seen[ny][nx] = True
                        stack.append((nx,ny))
            if 5 < len(pts) < 5000:
                xs = [p[0] for p in pts]
                ys = [p[1] for p in pts]
                blobs.append((len(pts), sum(xs)/len(pts), sum(ys)/len(pts), min(xs), max(xs), min(ys), max(ys)))
